(272080, 18359, 2344, '<td valign="top">I see you adjusted your intensity and brightness levels. If I may make a suggestion and that''s to ease up on it, you''ve blown out your highlights and you''ve lost most of the detail there would have been in those petals. This would have been a very lovely image if you had just kept the post processing to a minimum</td>', 'I see you adjusted your intensity and brightness levels. If I may make a suggestion and that''s to ease up on it, you''ve blown out your highlights and you''ve lost most of the detail there would have been in those petals. This would have been a very lovely image if you had just kept the post processing to a minimum', '2003-04-21 09:17:14.000000', NULL, 1),
(272101, 18723, 7800, '<td valign="top">A little too much empty frame on the right, I think.</td>', 'A little too much empty frame on the right, I think.', '2003-04-21 09:54:50.000000', NULL, 1),
(272106, 18917, 7800, '<td valign="top">I feel like the dark border is too thick and the flowers are too close to the edge of the frame. My eye is drawn to the dark spot in the middle.</td>', 'I feel like the dark border is too thick and the flowers are too close to the edge of the frame. My eye is drawn to the dark spot in the middle.', '2003-04-21 10:05:00.000000', NULL, 1),
(272111, 18695, 2130, '<td valign="top">I would have liked to see a closeup of the shoe...it´s wonderful and old and interesting...</td>', 'I would have liked to see a closeup of the shoe...it´s wonderful and old and interesting...', '2003-04-21 10:16:14.000000', NULL, 1),
(272113, 18948, 4411, '<td valign="top">A flower shot in B&amp;W seems a strange concept to me, bu this works well.<br/>The leaves are a bit distracting but otherwised this is great, well done.</td>', 'A flower shot in B&W seems a strange concept to me, bu this works well.The leaves are a bit distracting but otherwised this is great, well done.', '2003-04-21 10:18:30.000000', NULL, 1),
(272125, 18759, 92, '<td valign="top">Great texture and DOF ! This is unique and very well done.</td>', 'Great texture and DOF ! This is unique and very well done.', '2003-04-21 10:36:57.000000', NULL, 1),
(272128, 18386, 92, '<td valign="top">What a unique flower. I don''t think I''ve ever seen one before. The light and composition are perfect.</td>', 'What a unique flower. I don''t think I''ve ever seen one before. The light and composition are perfect.', '2003-04-21 10:38:20.000000', NULL, 1),
(272131, 18783, 92, '<td valign="top">Beautiful. White is hard to photograph well but you nailed it. The DOF and composition are great :)</td>', 'Beautiful. White is hard to photograph well but you nailed it. The DOF and composition are great :)', '2003-04-21 10:41:57.000000', NULL, 1),
(272136, 18724, 92, '<td valign="top">Beautiful !  I love the lighing on this one as well as the DOF used.</td>', 'Beautiful !  I love the lighing on this one as well as the DOF used.', '2003-04-21 10:44:30.000000', NULL, 1),
(272138, 18860, 92, '<td valign="top">WONDERFUL color and DOF !!!</td>', 'WONDERFUL color and DOF !!!', '2003-04-21 10:44:59.000000', NULL, 1),
(272139, 18843, 92, '<td valign="top">The light and composition are just wonderful !!!!!</td>', 'The light and composition are just wonderful !!!!!', '2003-04-21 10:45:34.000000', NULL, 1),
(272140, 18880, 92, '<td valign="top">My only suggestion would be to crop out the cement on the bottom left. The white looks so soft in the lighting. Very nice :)</td>', 'My only suggestion would be to crop out the cement on the bottom left. The white looks so soft in the lighting. Very nice :)', '2003-04-21 10:47:14.000000', NULL, 1),
(272141, 18970, 92, '<td valign="top">WOW ! such nice reach color. The DOF is perfect ! This is beautiful !</td>', 'WOW ! such nice reach color. The DOF is perfect ! This is beautiful !', '2003-04-21 10:47:51.000000', NULL, 1),
(272142, 18830, 92, '<td valign="top">I would hang this on my bedroom wall ! The white isn''t overblown and has such nice lighting. PERFECT compostion. LOVE it !</td>', 'I would hang this on my bedroom wall ! The white isn''t overblown and has such nice lighting. PERFECT compostion. LOVE it !', '2003-04-21 10:48:40.000000', NULL, 1),
(272146, 18715, 92, '<td valign="top">The first word to come out of my mouth was OMG WOW ! The color, flower choice, compostion, lighting...wow it''s all just amazing. I love this photo. My only 10 so far !</td>', 'The first word to come out of my mouth was OMG WOW ! The color, flower choice, compostion, lighting...wow it''s all just amazing. I love this photo. My only 10 so far !', '2003-04-21 10:50:22.000000', NULL, 1),
(272147, 18893, 92, '<td valign="top">I love the abstract look of this. The clairity and color are beautiful !</td>', 'I love the abstract look of this. The clairity and color are beautiful !', '2003-04-21 10:50:54.000000', NULL, 1),
(272148, 18752, 92, '<td valign="top">Delicate AND beautiful ! Perfect light and DOF. This is really nice.</td>', 'Delicate AND beautiful ! Perfect light and DOF. This is really nice.', '2003-04-21 10:51:56.000000', NULL, 1),
(272149, 18924, 92, '<td valign="top">Perfect against the black. I love this phot. I can only say you just nailed it :)</td>', 'Perfect against the black. I love this phot. I can only say you just nailed it :)', '2003-04-21 10:52:54.000000', NULL, 1),
(272150, 18633, 92, '<td valign="top">PERFECT time of day, the light is great. Color and composition rock !</td>', 'PERFECT time of day, the light is great. Color and composition rock !', '2003-04-21 10:53:48.000000', NULL, 1);
