(272612, 18917, 342, '<td valign="top">this seems to lack a central focal point, i do like the orange flowers</td>', 'this seems to lack a central focal point, i do like the orange flowers', '2003-04-21 17:10:37.000000', NULL, 1),
(272613, 18855, 342, '<td valign="top">nice use of light and shadow.</td>', 'nice use of light and shadow.', '2003-04-21 17:10:54.000000', NULL, 1),
(272617, 18367, 7628, '<td valign="top">the photo gives a sense of the context of the flora  - the blades of grass poking up between the braod leaves, the dark soil beneath, the unopenned buds, and full flowers.  The composition is a bit too random, and the lack of focus in the back right corner is arbitrary - having everything sharp would work better.</td>', 'the photo gives a sense of the context of the flora  - the blades of grass poking up between the braod leaves, the dark soil beneath, the unopenned buds, and full flowers.  The composition is a bit too random, and the lack of focus in the back right corner is arbitrary - having everything sharp would work better.', '2003-04-21 17:20:08.000000', NULL, 1),
(272618, 18863, 7639, '<td valign="top">A powerful composition - it has a timeless quality.</td>', 'A powerful composition - it has a timeless quality.', '2003-04-21 17:20:37.000000', NULL, 1),
(272619, 18913, 1202, '<td valign="top">How important to your picture is the No Parking sign?   I think I would have left it out.</td>', 'How important to your picture is the No Parking sign?   I think I would have left it out.', '2003-04-21 17:21:11.000000', NULL, 1),
