(273114, 18653, 5767, '<td valign="top">Great repeatitive theme in the background.  Good use of your focal depth and excellent exposure and composition. High rankings for this one.</td>', 'Great repeatitive theme in the background.  Good use of your focal depth and excellent exposure and composition. High rankings for this one.', '2003-04-22 03:23:08.000000', NULL, 1),
(273115, 18952, 5767, '<td valign="top">Composition is a bit ackward and seems to crop off too much of the subject disproportionately.  Exposure and saturation also seem a little on the dark side (maybe too much of a cloudy day to photograph brightly colored subjects).  Background bush is also a little distracting.</td>', 'Composition is a bit ackward and seems to crop off too much of the subject disproportionately.  Exposure and saturation also seem a little on the dark side (maybe too much of a cloudy day to photograph brightly colored subjects).  Background bush is also a little distracting.', '2003-04-22 03:24:39.000000', NULL, 1),
(273116, 18974, 5767, '<td valign="top">One quality to these macro shots that sets others apart as "outstanding" from just "good" is their uniform lighting and their solid backgrounds.  Here there are some "hot spots" that are distracting and the overall exposure seems low which is preventing some of the details and color from standing out.</td>', 'One quality to these macro shots that sets others apart as "outstanding" from just "good" is their uniform lighting and their solid backgrounds.  Here there are some "hot spots" that are distracting and the overall exposure seems low which is preventing some of the details and color from standing out.', '2003-04-22 03:26:25.000000', NULL, 1),
(273117, 18887, 5767, '<td valign="top">Neat use of a path through the image.  I like that it leads me through the photograph.</td>', 'Neat use of a path through the image.  I like that it leads me through the photograph.', '2003-04-22 03:27:10.000000', NULL, 1),
(273119, 18906, 5767, '<td valign="top">Very uneven exposure - very over to very under exposed.  Lots of detail in the background is also distracting.  Beautiful colors really make this eye catching.</td>', 'Very uneven exposure - very over to very under exposed.  Lots of detail in the background is also distracting.  Beautiful colors really make this eye catching.', '2003-04-22 03:28:10.000000', NULL, 1),
(273120, 18924, 5767, '<td valign="top">WOW on this one.  The lighting, background, exposure and detail captured is perfectly done.  Your composition and perspective are creative.  high marks for this one.</td>', 'WOW on this one.  The lighting, background, exposure and detail captured is perfectly done.  Your composition and perspective are creative.  high marks for this one.', '2003-04-22 03:28:55.000000', NULL, 1),
(273121, 18639, 5767, '<td valign="top">Extremely grainy with lots of noise in the night sky and grass which seems to blow out the detail in the trees, too.  The clarity and "night" feeling are lost.</td>', 'Extremely grainy with lots of noise in the night sky and grass which seems to blow out the detail in the trees, too.  The clarity and "night" feeling are lost.', '2003-04-22 03:30:23.000000', NULL, 1),
(273122, 18839, 5767, '<td valign="top">Nice lighitng and color patterns.  These are different types of tulips than in other images, which is refreshing.</td>', 'Nice lighitng and color patterns.  These are different types of tulips than in other images, which is refreshing.', '2003-04-22 03:30:57.000000', NULL, 1),
(273123, 18783, 5767, '<td valign="top">This is a little underexposed with some relatively very bright light pulling me away from the subject.  The tones around the flower are too near that of your subject so it gets lost in the background.  The white on the flower is also kind of greyish which causes lots of detail to be lost.  Highlight on the tip has all detail blown out from it, too.</td>', 'This is a little underexposed with some relatively very bright light pulling me away from the subject.  The tones around the flower are too near that of your subject so it gets lost in the background.  The white on the flower is also kind of greyish which causes lots of detail to be lost.  Highlight on the tip has all detail blown out from it, too.', '2003-04-22 03:32:53.000000', NULL, 1),
(273124, 18809, 5767, '<td valign="top">Oooooh.  This is nice.  Great color, nice lighting.  Good use of repeative patterns.</td>', 'Oooooh.  This is nice.  Great color, nice lighting.  Good use of repeative patterns.', '2003-04-22 03:33:42.000000', NULL, 1),
(273125, 18886, 5767, '<td valign="top">Classic tulip image.  Good detail.  I particularly like how you''ve positioned the leaves and stem in your impage.</td>', 'Classic tulip image.  Good detail.  I particularly like how you''ve positioned the leaves and stem in your impage.', '2003-04-22 03:34:36.000000', NULL, 1),
(273126, 18959, 5767, '<td valign="top">Hard to tell that flora was the subject of this photograph.  The shadows are so prevalent that the ones from the tree blend in with others on the ground.  Needs to be more separation in tones here for it to be as effective as it could be.</td>', 'Hard to tell that flora was the subject of this photograph.  The shadows are so prevalent that the ones from the tree blend in with others on the ground.  Needs to be more separation in tones here for it to be as effective as it could be.', '2003-04-22 03:35:36.000000', NULL, 1),
(273127, 18889, 5767, '<td valign="top">Interesting detail you''ve found here.  Exposure is a bit too high, though.</td>', 'Interesting detail you''ve found here.  Exposure is a bit too high, though.', '2003-04-22 03:35:56.000000', NULL, 1),
(273128, 18327, 5767, '<td valign="top">Lines, lines everywhere.  I like the anges they''ve created.  Flowers really stand out from the white and green.  Good entry.</td>', 'Lines, lines everywhere.  I like the anges they''ve created.  Flowers really stand out from the white and green.  Good entry.', '2003-04-22 03:36:35.000000', NULL, 1),
(273129, 18731, 5767, '<td valign="top">Interesting submission.  You''ve composed a unique way of looking at the tulip fields.  I like the originality and the juxtaposition in the "mood" between the brightness and newness of the flowers against the grey sky and barren tree.  I think you''ve done a great job with this one.  One minor nick is the tree branch on the right.  Once it''s noticed, it''s hard to stop looking at.  But, again, that''s minor.</td>', 'Interesting submission.  You''ve composed a unique way of looking at the tulip fields.  I like the originality and the juxtaposition in the "mood" between the brightness and newness of the flowers against the grey sky and barren tree.  I think you''ve done a great job with this one.  One minor nick is the tree branch on the right.  Once it''s noticed, it''s hard to stop looking at.  But, again, that''s minor.', '2003-04-22 03:38:19.000000', NULL, 1),
(273131, 18863, 5767, '<td valign="top">Hard to tell that this is a flora entry.  But I''ll take ownership for that and chalk it up to not seeing your vision.  Technically the colors are perfectly saturated and I like how you''ve captured the details in the rocks.  The angles created by your composition make this nice to look at.</td>', 'Hard to tell that this is a flora entry.  But I''ll take ownership for that and chalk it up to not seeing your vision.  Technically the colors are perfectly saturated and I like how you''ve captured the details in the rocks.  The angles created by your composition make this nice to look at.', '2003-04-22 03:40:02.000000', NULL, 1),
(273132, 18679, 5767, '<td valign="top">Great combination of colors here.  Perfectly exposed and you''ve captured some nice details in the petals and leaves.</td>', 'Great combination of colors here.  Perfectly exposed and you''ve captured some nice details in the petals and leaves.', '2003-04-22 03:40:42.000000', NULL, 1),
(273133, 18858, 5767, '<td valign="top">Good lighting and excellent composition.  For this to be an outstanding image you''d need a little more sharpness to it, but overall this is very good.</td>', 'Good lighting and excellent composition.  For this to be an outstanding image you''d need a little more sharpness to it, but overall this is very good.', '2003-04-22 03:41:41.000000', NULL, 1),
(273134, 18358, 5767, '<td valign="top">Interesting color combinations.  I didn''t like it at first, but as I type my comments it grows on me.  New flower growing on bed of dead leaves.  You''ve told a nice story and conveyed your vision (if I guessed it) well.  Composition is also very well done here to have framed the flower (without cutting off its leaves) and its shadow.</td>', 'Interesting color combinations.  I didn''t like it at first, but as I type my comments it grows on me.  New flower growing on bed of dead leaves.  You''ve told a nice story and conveyed your vision (if I guessed it) well.  Composition is also very well done here to have framed the flower (without cutting off its leaves) and its shadow.', '2003-04-22 03:43:15.000000', NULL, 1),
(273135, 18830, 4871, '<td valign="top">Nicely contrasted. and I like how the whites are not getting lost</td>', 'Nicely contrasted. and I like how the whites are not getting lost', '2003-04-22 03:44:13.000000', NULL, 1),
(273136, 18823, 5767, '<td valign="top">Oooooh.  Now here''s an example of an excellent flower shot.  I think I recognize this photographer''s style.  High marks for clarity, color usage, and background desaturation.</td>', 'Oooooh.  Now here''s an example of an excellent flower shot.  I think I recognize this photographer''s style.  High marks for clarity, color usage, and background desaturation.', '2003-04-22 03:44:29.000000', NULL, 1),
(273137, 18948, 5767, '<td valign="top">The flash really caused a harshness on an image that is crying for softness and detail.  The is still a beautiful composition and use of B&amp;W.</td>', 'The flash really caused a harshness on an image that is crying for softness and detail.  The is still a beautiful composition and use of B&W.', '2003-04-22 03:45:27.000000', NULL, 1),
(273138, 18634, 4871, '<td valign="top">I found it a bit distracting the greenery at the bottom being cropped or not included. Great shot though!</td>', 'I found it a bit distracting the greenery at the bottom being cropped or not included. Great shot though!', '2003-04-22 03:46:08.000000', NULL, 1),
(273139, 18843, 4871, '<td valign="top">Love the color of the clouds matching the reids. Well done!</td>', 'Love the color of the clouds matching the reids. Well done!', '2003-04-22 03:46:39.000000', NULL, 1),
(273140, 18897, 5767, '<td valign="top">This is very overexposed which has blown out all the important detail and created a very harsh image of some very soft and delicate subjects.</td>', 'This is very overexposed which has blown out all the important detail and created a very harsh image of some very soft and delicate subjects.', '2003-04-22 03:46:44.000000', NULL, 1),
(273141, 18637, 5767, '<td valign="top">Very blurry which has caused a loss of all detail in the flower''s petals.  The idea behind this is an excellent use of color and composition.</td>', 'Very blurry which has caused a loss of all detail in the flower''s petals.  The idea behind this is an excellent use of color and composition.', '2003-04-22 03:48:03.000000', NULL, 1),
(273142, 18715, 4871, '<td valign="top">Beautifully shot and I love the contrast!</td>', 'Beautifully shot and I love the contrast!', '2003-04-22 03:48:39.000000', NULL, 1),
(273143, 18723, 4871, '<td valign="top">Wow! I love the shadows and the background is sensational! I''d love to know how you got that gradient happening. 9</td>', 'Wow! I love the shadows and the background is sensational! I''d love to know how you got that gradient happening. 9', '2003-04-22 03:49:25.000000', NULL, 1),
(273144, 18922, 5767, '<td valign="top">This use of a close color range really brings the subject to the forefront and creates a nice "bed" as a backdrop.  I like what you''ve done here a lot.  Great clarity and lighting.</td>', 'This use of a close color range really brings the subject to the forefront and creates a nice "bed" as a backdrop.  I like what you''ve done here a lot.  Great clarity and lighting.', '2003-04-22 03:49:30.000000', NULL, 1),
(273145, 18383, 5767, '<td valign="top">It is real flowers on a painting.  Very clever.  Beautiful execution, too.  High marks for this one.</td>', 'It is real flowers on a painting.  Very clever.  Beautiful execution, too.  High marks for this one.', '2003-04-22 03:50:30.000000', NULL, 1),
(273146, 18838, 4871, '<td valign="top">Hmmm - lets see we have a house, power-lines, a stop sign, Oh, and a tree!</td>', 'Hmmm - lets see we have a house, power-lines, a stop sign, Oh, and a tree!', '2003-04-22 03:50:31.000000', NULL, 1),
(273147, 18559, 4871, '<td valign="top">I love this pic! Nice work on framing :)</td>', 'I love this pic! Nice work on framing :)', '2003-04-22 03:51:09.000000', NULL, 1),
(273148, 18452, 5767, '<td valign="top">Great macro.  These are hard to do for so many reasons (which is why I  don''t do them).  But you''ve done an excellent job with this.  Excellent detail and exposure.</td>', 'Great macro.  These are hard to do for so many reasons (which is why I  don''t do them).  But you''ve done an excellent job with this.  Excellent detail and exposure.', '2003-04-22 03:51:32.000000', NULL, 1),
(273149, 18733, 4871, '<td valign="top">Not as sharp as I''d be wanting to see in a macro.</td>', 'Not as sharp as I''d be wanting to see in a macro.', '2003-04-22 03:51:44.000000', NULL, 1),
(273150, 18741, 4871, '<td valign="top">I think that the green in the foreground covering your purple takes away from the shot. Otherwise its great!</td>', 'I think that the green in the foreground covering your purple takes away from the shot. Otherwise its great!', '2003-04-22 03:52:19.000000', NULL, 1),
(273151, 18885, 5767, '<td valign="top">Very creative and eye catching.  Your composition is excellent and is what (in my opinion) makes this an excellent entry.</td>', 'Very creative and eye catching.  Your composition is excellent and is what (in my opinion) makes this an excellent entry.', '2003-04-22 03:52:23.000000', NULL, 1),
(273152, 18687, 5767, '<td valign="top">Very overexposed which has caused the loss of a lot of detail and has caused very little saturation in the important colors.</td>', 'Very overexposed which has caused the loss of a lot of detail and has caused very little saturation in the important colors.', '2003-04-22 03:53:15.000000', NULL, 1),
(273153, 18910, 4871, '<td valign="top">Now this is one of my favourites! Def in the top 3! Love the detail, the lighting... a true representation of fauna too. Fantastic :) 10</td>', 'Now this is one of my favourites! Def in the top 3! Love the detail, the lighting... a true representation of fauna too. Fantastic :) 10', '2003-04-22 03:53:32.000000', NULL, 1),
(273154, 18720, 5767, '<td valign="top">Nice angles and colors.  The flowi-ness (my own technical term) of the leaves adds a lot to this.  Nice background, too.</td>', 'Nice angles and colors.  The flowi-ness (my own technical term) of the leaves adds a lot to this.  Nice background, too.', '2003-04-22 03:54:09.000000', NULL, 1),
(273155, 18522, 5767, '<td valign="top">You''ve lost some focus on your main subject and the rocks at its base got it instead.  This is a good idea.  Your exposure was right on and the colors of all the rocks against the tree works well, too.</td>', 'You''ve lost some focus on your main subject and the rocks at its base got it instead.  This is a good idea.  Your exposure was right on and the colors of all the rocks against the tree works well, too.', '2003-04-22 03:55:16.000000', NULL, 1),
(273156, 18758, 4871, '<td valign="top">Its a bit green!</td>', 'Its a bit green!', '2003-04-22 03:58:20.000000', NULL, 1),
(273157, 18948, 4871, '<td valign="top">Love the shot, but have you made this into B&amp;W? If so I think this spoils it a bit. Also it appears to have been a bit grainy. Otherwise I love it.</td>', 'Love the shot, but have you made this into B&W? If so I think this spoils it a bit. Also it appears to have been a bit grainy. Otherwise I love it.', '2003-04-22 04:00:28.000000', NULL, 1),
(273158, 18695, 4871, '<td valign="top">Are your shoes that bad??? :-D Great shot!</td>', 'Are your shoes that bad??? :-D Great shot!', '2003-04-22 04:01:27.000000', NULL, 1),
(273159, 18944, 5767, '<td valign="top">Beautiful lines and great lighting for this image.  Nice detail and sharpness, too.  The brown spots (although) natural are pretty distracting since they are in such contrast in many ways to the leaf.</td>', 'Beautiful lines and great lighting for this image.  Nice detail and sharpness, too.  The brown spots (although) natural are pretty distracting since they are in such contrast in many ways to the leaf.', '2003-04-22 04:02:17.000000', NULL, 1),
(273160, 18970, 4871, '<td valign="top">Like it, but it seems a bit unbalanced. Seems to be a bit too much ''nothing'' on the left and too much on the right. Love the detail though!</td>', 'Like it, but it seems a bit unbalanced. Seems to be a bit too much ''nothing'' on the left and too much on the right. Love the detail though!', '2003-04-22 04:02:35.000000', NULL, 1),
(273161, 18386, 5767, '<td valign="top">Unique entry.  Good choice for this one.  They''re weird, but beautiful.  Technically this is well done, too.</td>', 'Unique entry.  Good choice for this one.  They''re weird, but beautiful.  Technically this is well done, too.', '2003-04-22 04:03:27.000000', NULL, 1),
(273162, 18506, 4871, '<td valign="top">I like the soft look here and a fabulous representation of fauna. The only thing I''m thinking here though is that while the most of this picture is dead trees, the green in the foreground seems a bit out of place. But I still like it.</td>', 'I like the soft look here and a fabulous representation of fauna. The only thing I''m thinking here though is that while the most of this picture is dead trees, the green in the foreground seems a bit out of place. But I still like it.', '2003-04-22 04:03:59.000000', NULL, 1),
(273163, 18634, 5767, '<td valign="top">Nice color selections for your backdrop.</td>', 'Nice color selections for your backdrop.', '2003-04-22 04:04:00.000000', NULL, 1),
(273164, 18910, 5767, '<td valign="top">This one just works well.  Good color (a little over exposed) and excellent detail in the sand.</td>', 'This one just works well.  Good color (a little over exposed) and excellent detail in the sand.', '2003-04-22 04:04:55.000000', NULL, 1),
(273165, 18759, 5767, '<td valign="top">Very nice.  Great texture, color and exposure balance.</td>', 'Very nice.  Great texture, color and exposure balance.', '2003-04-22 04:05:18.000000', NULL, 1),
(273166, 18404, 5767, '<td valign="top">Very overexposed and grainy, but I like your subjects and pattern you''ve created.</td>', 'Very overexposed and grainy, but I like your subjects and pattern you''ve created.', '2003-04-22 04:06:00.000000', NULL, 1),
(273167, 18393, 5767, '<td valign="top">Beautiful, natural rose image.</td>', 'Beautiful, natural rose image.', '2003-04-22 04:06:15.000000', NULL, 1),
(273168, 18679, 4871, '<td valign="top">Wow!!! Fantastic!!! Where did you find this! I''m in two minds about the croping top right though. The splash of white definitely adds to the picture, but the black seems to take away from the beautiful colors. Gave it 9</td>', 'Wow!!! Fantastic!!! Where did you find this! I''m in two minds about the croping top right though. The splash of white definitely adds to the picture, but the black seems to take away from the beautiful colors. Gave it 9', '2003-04-22 04:06:16.000000', NULL, 1),
(273169, 18358, 4871, '<td valign="top">Great picture! What a fantastic idea :)</td>', 'Great picture! What a fantastic idea :)', '2003-04-22 04:07:09.000000', NULL, 1),
(273170, 18680, 5767, '<td valign="top">Wonderful image.  Very unique concept, great execution.  Overall high marks!</td>', 'Wonderful image.  Very unique concept, great execution.  Overall high marks!', '2003-04-22 04:08:04.000000', NULL, 1),
(273171, 18510, 4871, '<td valign="top">Love it! Great title!</td>', 'Love it! Great title!', '2003-04-22 04:08:08.000000', NULL, 1),
(273172, 18855, 5767, '<td valign="top">simple and beautiful.  Great lighting, nice background, excellent details.</td>', 'simple and beautiful.  Great lighting, nice background, excellent details.', '2003-04-22 04:08:33.000000', NULL, 1),
(273173, 18834, 4871, '<td valign="top">What an amazing sight to see! I wish there was these kind of fields in Australia! Very impressive.</td>', 'What an amazing sight to see! I wish there was these kind of fields in Australia! Very impressive.', '2003-04-22 04:10:02.000000', NULL, 1),
(273174, 18843, 5767, '<td valign="top">Love the colors and composition.  Nice that you were brave enough to depart from the "beautiful", delicate flower choices and pick these.  Your exposure and texture details are well done.</td>', 'Love the colors and composition.  Nice that you were brave enough to depart from the "beautiful", delicate flower choices and pick these.  Your exposure and texture details are well done.', '2003-04-22 04:10:43.000000', NULL, 1),
(273175, 18932, 5767, '<td valign="top">I love all the lines drawing me in and out of the main part of the flower.  Your focal depth is wonderfully done, too.  Exposure is right on and the highlights just "snap".  I think you did a nice job with this one.</td>', 'I love all the lines drawing me in and out of the main part of the flower.  Your focal depth is wonderfully done, too.  Exposure is right on and the highlights just "snap".  I think you did a nice job with this one.', '2003-04-22 04:12:02.000000', NULL, 1),
(273176, 18893, 5767, '<td valign="top">Nice macro shot here.  Good detail and texture.</td>', 'Nice macro shot here.  Good detail and texture.', '2003-04-22 04:12:53.000000', NULL, 1),
(273177, 18860, 5767, '<td valign="top">I like the varity in color for this tulip entry.  This works well with the lighting and compositionl</td>', 'I like the varity in color for this tulip entry.  This works well with the lighting and compositionl', '2003-04-22 04:13:25.000000', NULL, 1),
(273178, 18715, 5767, '<td valign="top">The colors are amazing and so is the delicate detail.  You''ve taken a great detail of care with these and their images.</td>', 'The colors are amazing and so is the delicate detail.  You''ve taken a great detail of care with these and their images.', '2003-04-22 04:14:20.000000', NULL, 1),
(273179, 18359, 5767, '<td valign="top">Clever use of the repeatitive patterns.  A little overexposed for this one because it blows out the richness of the yellows down the line.  Still a good entry.</td>', 'Clever use of the repeatitive patterns.  A little overexposed for this one because it blows out the richness of the yellows down the line.  Still a good entry.', '2003-04-22 04:15:37.000000', NULL, 1),
(273181, 18823, 4569, '<td valign="top">Excellent focus and good colours</td>', 'Excellent focus and good colours', '2003-04-22 04:45:26.000000', NULL, 1),
(273183, 18715, 5728, '<td valign="top">My favourite for the challenge. Nothing at all to criticize about here, the lighting is wonderful. Why can''t I get my lighting like that? A perfect 10!</td>', 'My favourite for the challenge. Nothing at all to criticize about here, the lighting is wonderful. Why can''t I get my lighting like that? A perfect 10!', '2003-04-22 05:02:33.000000', NULL, 1),
(273184, 18783, 5728, '<td valign="top">Lovely and soft image. I would have 10''ed it except for the harsh light at the top of the flower. The lighting is a little too extreme between the top of the flower and the bottom - 9.</td>', 'Lovely and soft image. I would have 10''ed it except for the harsh light at the top of the flower. The lighting is a little too extreme between the top of the flower and the bottom - 9.', '2003-04-22 05:05:17.000000', NULL, 1),
(273190, 18885, 8058, '<td valign="top">Great Photo, Gives the feeling of an underwater wonderland.</td>', 'Great Photo, Gives the feeling of an underwater wonderland.', '2003-04-22 05:21:41.000000', NULL, 1),
(273191, 18809, 5728, '<td valign="top">Beautiful colors and lighting! The crop is a little too tight on the red border, the flowers may have benefitted from a little breathing space at the sides, or maybe enlargen the red border a couple of millimeters - 9.</td>', 'Beautiful colors and lighting! The crop is a little too tight on the red border, the flowers may have benefitted from a little breathing space at the sides, or maybe enlargen the red border a couple of millimeters - 9.', '2003-04-22 05:42:18.000000', NULL, 1),
(273193, 18452, 5728, '<td valign="top">Great macro, the color combination is in harmony, a very good pic - 9.</td>', 'Great macro, the color combination is in harmony, a very good pic - 9.', '2003-04-22 05:43:53.000000', NULL, 1),
(273194, 18723, 5728, '<td valign="top">Excellent pic, the shallow DOF works well here - 9.</td>', 'Excellent pic, the shallow DOF works well here - 9.', '2003-04-22 05:44:09.000000', NULL, 1),
(273195, 18910, 5728, '<td valign="top">Those greens are awesome, the lighting is spot on. The shallow DOF works well - 9.</td>', 'Those greens are awesome, the lighting is spot on. The shallow DOF works well - 9.', '2003-04-22 05:45:16.000000', NULL, 1),
(273196, 18855, 5728, '<td valign="top">Beautiful! Well thought out and well composed, very symmetrical - 9.</td>', 'Beautiful! Well thought out and well composed, very symmetrical - 9.', '2003-04-22 05:46:00.000000', NULL, 1),
(273198, 18759, 5728, '<td valign="top">Beautiful pic, the only mushroom one I''ve seen in this challenge. I like the way the main mushroom a the front is lightened up like that, as if it is in the spotlight - 9.</td>', 'Beautiful pic, the only mushroom one I''ve seen in this challenge. I like the way the main mushroom a the front is lightened up like that, as if it is in the spotlight - 9.', '2003-04-22 05:48:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(273199, 18744, 5728, '<td valign="top">Wonderful, simple and well done. You can see in this pic how spring flowers bring color into dullness. I find it could have been just a little lighter - 9.</td>', 'Wonderful, simple and well done. You can see in this pic how spring flowers bring color into dullness. I find it could have been just a little lighter - 9.', '2003-04-22 05:49:50.000000', NULL, 1),
(273200, 18839, 5728, '<td valign="top">Beautiful, no criticism here!</td>', 'Beautiful, no criticism here!', '2003-04-22 05:50:28.000000', NULL, 1),
(273201, 18853, 5728, '<td valign="top">Those daisies stand out well on the blue background, good idea. Yellow on blue always works well - 8.</td>', 'Those daisies stand out well on the blue background, good idea. Yellow on blue always works well - 8.', '2003-04-22 06:00:20.000000', NULL, 1),
(273202, 18970, 5728, '<td valign="top">The shallow DOF works well here.  The colors are so mellow and pastel like, good job - 8.</td>', 'The shallow DOF works well here.  The colors are so mellow and pastel like, good job - 8.', '2003-04-22 06:01:31.000000', NULL, 1),
(273203, 18680, 5728, '<td valign="top">Interesting effect with the blue in the background. You can never go wrong with yellow on blue, good idea - 8.</td>', 'Interesting effect with the blue in the background. You can never go wrong with yellow on blue, good idea - 8.', '2003-04-22 06:02:25.000000', NULL, 1),
(273204, 18386, 5728, '<td valign="top">The pollen on the flowers surface is a cool effect. The composition is very good, only the white spots in the background are disturbing - 8.<br/><br/><i>Message edited by author 2003-04-30 06:21:42.</i></td>', 'The pollen on the flowers surface is a cool effect. The composition is very good, only the white spots in the background are disturbing - 8.', '2003-04-22 06:03:50.000000', '2003-04-30 07:21:42.000000', 1),
