(273973, 18916, 6870, '<td valign="top">To have found one of these in the wild is an accomplishment unto itself. The composition works well here to emphasize the uniqueness of these blossoms. Sharp focus and DOF really enhance this, too. 10</td>', 'To have found one of these in the wild is an accomplishment unto itself. The composition works well here to emphasize the uniqueness of these blossoms. Sharp focus and DOF really enhance this, too. 10', '2003-04-23 00:29:01.000000', NULL, 1),
(273974, 18912, 6870, '<td valign="top">The perfect point of view to provide us a look at this wonderful scene. The mottled patterns the flowers make in the image is wonderful, and is set off well by the trees. Lighting is soft and brings out the color of, well, of everything. The sky is kind of drab, but you really need the tops of those trees. Nicely done.</td>', 'The perfect point of view to provide us a look at this wonderful scene. The mottled patterns the flowers make in the image is wonderful, and is set off well by the trees. Lighting is soft and brings out the color of, well, of everything. The sky is kind of drab, but you really need the tops of those trees. Nicely done.', '2003-04-23 00:30:47.000000', NULL, 1),
(273975, 18960, 6870, '<td valign="top">The title does nothing for me here, but this extreme macro is lovely, providing us a close up while still emphasizing the mystery of beauty this flower communicates. Nice focus throughout.</td>', 'The title does nothing for me here, but this extreme macro is lovely, providing us a close up while still emphasizing the mystery of beauty this flower communicates. Nice focus throughout.', '2003-04-23 00:32:02.000000', NULL, 1),
(273976, 18970, 6870, '<td valign="top">Sure wish we could grow these here in Utah. Our soil isn''t acid enough. This is a lovely shot,and I love how the bloom is placed so we can instantly see beyond it, as if this garden had even more to offer. Nice DOF and focus. Lighting is impeccable: soft and gentle with the gentle colors and textures of the flowers and leaves.</td>', 'Sure wish we could grow these here in Utah. Our soil isn''t acid enough. This is a lovely shot,and I love how the bloom is placed so we can instantly see beyond it, as if this garden had even more to offer. Nice DOF and focus. Lighting is impeccable: soft and gentle with the gentle colors and textures of the flowers and leaves.', '2003-04-23 00:33:46.000000', NULL, 1),
(273977, 18404, 7838, '<td valign="top">cant wait to see the detail on this picture.  i am sure that it has some meaning.</td>', 'cant wait to see the detail on this picture.  i am sure that it has some meaning.', '2003-04-23 00:35:33.000000', NULL, 1),
(273978, 18860, 1280, '<td valign="top">The colors are beautiful, but I really would rather see more of them in focus.  The purple one up front is real fine.</td>', 'The colors are beautiful, but I really would rather see more of them in focus.  The purple one up front is real fine.', '2003-04-23 00:35:37.000000', NULL, 1),
(273980, 18894, 6870, '<td valign="top">A unique and refreshing choice among all of these flowers! The main focus here are the leaves that are in focus, so while the out of focus leaves provide a lot of depth and interest, they may obscure the focused leaves just a tiny bit too much. Still, I like this idea and image alot. You may have oversharpened this image a bit too much: look at the unnatural white edges of the leaves. Still, this is a gentle, inviting image that I enjoy a lot.</td>', 'A unique and refreshing choice among all of these flowers! The main focus here are the leaves that are in focus, so while the out of focus leaves provide a lot of depth and interest, they may obscure the focused leaves just a tiny bit too much. Still, I like this idea and image alot. You may have oversharpened this image a bit too much: look at the unnatural white edges of the leaves. Still, this is a gentle, inviting image that I enjoy a lot.', '2003-04-23 00:36:34.000000', NULL, 1),
(273981, 18852, 7838, '<td valign="top">extremely well done.  i like this. nice closeup on the flower, but can still see the boy in background enought to understand what is going on in the pic.  every pic is worth a 1000 words.</td>', 'extremely well done.  i like this. nice closeup on the flower, but can still see the boy in background enought to understand what is going on in the pic.  every pic is worth a 1000 words.', '2003-04-23 00:37:23.000000', NULL, 1),
(273982, 18639, 6870, '<td valign="top">Very festive image that the reflection in the water emphasizes and enhaces greatly. The sky is a bit grainy, but the composition and arrangement (point of view) make this image really work for me.</td>', 'Very festive image that the reflection in the water emphasizes and enhaces greatly. The sky is a bit grainy, but the composition and arrangement (point of view) make this image really work for me.', '2003-04-23 00:37:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(273983, 18752, 1280, '<td valign="top">Beautifully arranged composition, well exposed, and good dof.  Very nice!</td>', 'Beautifully arranged composition, well exposed, and good dof.  Very nice!', '2003-04-23 00:38:27.000000', NULL, 1),
(273984, 18935, 7838, '<td valign="top">those finger prints match those on Most Wanted.. LOL. great detail</td>', 'those finger prints match those on Most Wanted.. LOL. great detail', '2003-04-23 00:38:56.000000', NULL, 1),
(273985, 18843, 6870, '<td valign="top">The cattails against the sky are really riveting. The sky seems to bring out their colors. It wouldn''t give a "boggy" feel, but that''s what I want to see more of in this image. Perhaps a closer point of view? Very nice job.</td>', 'The cattails against the sky are really riveting. The sky seems to bring out their colors. It wouldn''t give a "boggy" feel, but that''s what I want to see more of in this image. Perhaps a closer point of view? Very nice job.', '2003-04-23 00:39:31.000000', NULL, 1),
(273986, 18758, 7838, '<td valign="top">interesting pic.  i like the way you focused on the seeds instead of the "flower"</td>', 'interesting pic.  i like the way you focused on the seeds instead of the "flower"', '2003-04-23 00:39:39.000000', NULL, 1),
(273987, 18724, 7838, '<td valign="top">very nice</td>', 'very nice', '2003-04-23 00:40:12.000000', NULL, 1),
(273988, 18910, 6870, '<td valign="top">Intriguing and unique. I hope this does well! Focus and composition are perfect. 10</td>', 'Intriguing and unique. I hope this does well! Focus and composition are perfect. 10', '2003-04-23 00:40:47.000000', NULL, 1),
(273989, 18620, 1280, '<td valign="top">Interesting, creative, good dof, pretty coloring and markings.</td>', 'Interesting, creative, good dof, pretty coloring and markings.', '2003-04-23 00:40:47.000000', NULL, 1),
(273990, 18714, 7935, '<td valign="top">I really like the layout of this pic and fel it meets the challenge well  but it could use  little more DOF IMHO  this is probably my favorite flower pic<br/></td>', 'I really like the layout of this pic and fel it meets the challenge well  but it could use  little more DOF IMHO  this is probably my favorite flower pic', '2003-04-23 00:41:10.000000', NULL, 1),
(273991, 18687, 7838, '<td valign="top">beautiful try, but hard to tell what i am looking for.  I think this would have been better if the focus was on the bush, with the background a little out of focus.</td>', 'beautiful try, but hard to tell what i am looking for.  I think this would have been better if the focus was on the bush, with the background a little out of focus.', '2003-04-23 00:42:25.000000', NULL, 1),
(273992, 18393, 6870, '<td valign="top">What a super idea to have the rose backlit by the blue sky. You''ve managed to keep the gentleness of the light and the rose throughout. What an accomplishment. This image really shows off your skills at capturing light without having it burn the photo. The leaves here take a little too much of the focus here, but I''ll forgive that as I gaze at the light from this flower!</td>', 'What a super idea to have the rose backlit by the blue sky. You''ve managed to keep the gentleness of the light and the rose throughout. What an accomplishment. This image really shows off your skills at capturing light without having it burn the photo. The leaves here take a little too much of the focus here, but I''ll forgive that as I gaze at the light from this flower!', '2003-04-23 00:43:03.000000', NULL, 1),
(273994, 18705, 7935, '<td valign="top">nice effect with the fence and horse  meets the challenge well</td>', 'nice effect with the fence and horse  meets the challenge well', '2003-04-23 00:43:44.000000', NULL, 1),
(273995, 18791, 7607, '<td valign="top">Great colors. Wish the wave was more visible but then you would have had too much competition for your flower. Beautiful</td>', 'Great colors. Wish the wave was more visible but then you would have had too much competition for your flower. Beautiful', '2003-04-23 00:44:11.000000', NULL, 1),
(273996, 18912, 1280, '<td valign="top">Pretty!  Nice saturation.</td>', 'Pretty!  Nice saturation.', '2003-04-23 00:44:26.000000', NULL, 1),
(273997, 18912, 7935, '<td valign="top">very nice  meets the challenge   might have tried a polarizer to try to get some blue in the sky</td>', 'very nice  meets the challenge   might have tried a polarizer to try to get some blue in the sky', '2003-04-23 00:45:06.000000', NULL, 1),
(273999, 18770, 7607, '<td valign="top">This makes me feel like I could reach out an pick one of these. I love your bold composition and colors</td>', 'This makes me feel like I could reach out an pick one of these. I love your bold composition and colors', '2003-04-23 00:45:44.000000', NULL, 1),
(274000, 18630, 6523, '<td valign="top">This photo is curious because the background is in better focus than the flower.  Did you intend that to be what happened?  Do you have a camera that doesn''t have a macro setting?<br/> <br/>Also, I think you could have made a more dramatic photo by picking a blossom such as the one in the lower left corner that''s in some sunlight -- the highlights and shadows would give it some depth and some added interest.  <br/> <br/>I love dogwood, though, and it''s nice to see it in the challenge.<br/></td>', 'This photo is curious because the background is in better focus than the flower.  Did you intend that to be what happened?  Do you have a camera that doesn''t have a macro setting? Also, I think you could have made a more dramatic photo by picking a blossom such as the one in the lower left corner that''s in some sunlight -- the highlights and shadows would give it some depth and some added interest.   I love dogwood, though, and it''s nice to see it in the challenge.', '2003-04-23 00:46:06.000000', NULL, 1),
(274001, 18839, 6870, '<td valign="top">These little "native" tulips are so cute and so wild.You capture their essence of gentle wildness well with all of the angles and lines. I love how you''ve cropped the upper tulip. It gives a sense that you couldn''t quite capture ALL of their wildness: like giddy children who cannot sit still. Were these in sharp focus, the feelings here would be even more enhanced. Nice work.</td>', 'These little "native" tulips are so cute and so wild.You capture their essence of gentle wildness well with all of the angles and lines. I love how you''ve cropped the upper tulip. It gives a sense that you couldn''t quite capture ALL of their wildness: like giddy children who cannot sit still. Were these in sharp focus, the feelings here would be even more enhanced. Nice work.', '2003-04-23 00:46:16.000000', NULL, 1),
(274002, 18956, 1280, '<td valign="top">ooooh!  Pretty!   I like the way you completey filled the frame with the subject.  Lovely composition!!!</td>', 'ooooh!  Pretty!   I like the way you completey filled the frame with the subject.  Lovely composition!!!', '2003-04-23 00:46:28.000000', NULL, 1),
(274003, 18561, 7935, '<td valign="top">nice but DOF is kinda shallow  might try to focus further up the tree</td>', 'nice but DOF is kinda shallow  might try to focus further up the tree', '2003-04-23 00:47:24.000000', NULL, 1),
(274004, 18821, 7838, '<td valign="top">awesome pic.  great angle. nice barn, sun at a great angle.  throw a border on this one, and it could sell</td>', 'awesome pic.  great angle. nice barn, sun at a great angle.  throw a border on this one, and it could sell', '2003-04-23 00:47:31.000000', NULL, 1),
(274005, 18921, 7607, '<td valign="top">Unusual color and bold composition. Very nice</td>', 'Unusual color and bold composition. Very nice', '2003-04-23 00:47:40.000000', NULL, 1),
(274006, 18976, 6523, '<td valign="top">Nice use of soft focus.  Nice colors, too, in this  . . . uh . . . tulip?</td>', 'Nice use of soft focus.  Nice colors, too, in this  . . . uh . . . tulip?', '2003-04-23 00:48:32.000000', NULL, 1),
(274007, 18791, 6870, '<td valign="top">You''ve captured wonderful light on these little blossoms: the sun seems warm and bright as it should at the beach, but the image doesn''t seem washed out at all. Your skill with light is remarkable and it shows off well here. The crashing wave does distract just a tad, but when I see the delicacy and colors of the flowers that seem gentle and bold at the same time, all is forgiven.</td>', 'You''ve captured wonderful light on these little blossoms: the sun seems warm and bright as it should at the beach, but the image doesn''t seem washed out at all. Your skill with light is remarkable and it shows off well here. The crashing wave does distract just a tad, but when I see the delicacy and colors of the flowers that seem gentle and bold at the same time, all is forgiven.', '2003-04-23 00:49:25.000000', NULL, 1),
(274008, 18809, 7607, '<td valign="top">Very nice composition.</td>', 'Very nice composition.', '2003-04-23 00:50:04.000000', NULL, 1),
(274009, 18889, 7935, '<td valign="top">it''s bark!  everything''s in focus and lighted well   but it''s still just bark</td>', 'it''s bark!  everything''s in focus and lighted well   but it''s still just bark', '2003-04-23 00:50:43.000000', NULL, 1),
(274010, 18971, 6870, '<td valign="top">One of my favorite flowers! They sure race the melting snow, don''t they. I don''t think people realize just how tiny these are. Did you use a macro lens? The emotion here is soft and full of wonder, and you''ve captured the random patterns of these wildflowers very effectively. The delicate and gentle light on these blooms is an accomplishment unto itself. Very nicely done. 10</td>', 'One of my favorite flowers! They sure race the melting snow, don''t they. I don''t think people realize just how tiny these are. Did you use a macro lens? The emotion here is soft and full of wonder, and you''ve captured the random patterns of these wildflowers very effectively. The delicate and gentle light on these blooms is an accomplishment unto itself. Very nicely done. 10', '2003-04-23 00:51:47.000000', NULL, 1),
(274011, 18916, 1280, '<td valign="top">How lovely!!!  I''m so glad you plugged the endangered status.  That''s responsible photography!!!  Good job photographing it too! 10!</td>', 'How lovely!!!  I''m so glad you plugged the endangered status.  That''s responsible photography!!!  Good job photographing it too! 10!', '2003-04-23 00:52:11.000000', NULL, 1),
(274012, 18951, 7935, '<td valign="top">ouch those look sharp!    background''s not too pretty  I woulda tried to reduce the DOF on this one.</td>', 'ouch those look sharp!    background''s not too pretty  I woulda tried to reduce the DOF on this one.', '2003-04-23 00:52:34.000000', NULL, 1),
(274013, 18971, 1280, '<td valign="top">Very pretty, good dof, good colors.</td>', 'Very pretty, good dof, good colors.', '2003-04-23 00:52:59.000000', NULL, 1),
(274014, 18875, 7838, '<td valign="top">nice clouds. good closeup of seedpod.</td>', 'nice clouds. good closeup of seedpod.', '2003-04-23 00:53:30.000000', NULL, 1),
(274015, 18731, 6523, '<td valign="top">Great atmosphere and colors in this photo.  I think I might crop the right side a little to remove the branch of the next tree and some of the red tulip bed that doesn''t go all the way to the horizon.  And I''d correct the horizon line so it''s level.<br/> <br/>I really like the feeling of the early spring it conveys.</td>', 'Great atmosphere and colors in this photo.  I think I might crop the right side a little to remove the branch of the next tree and some of the red tulip bed that doesn''t go all the way to the horizon.  And I''d correct the horizon line so it''s level. I really like the feeling of the early spring it conveys.', '2003-04-23 00:54:01.000000', NULL, 1),
(274016, 18831, 7838, '<td valign="top">i like the border.. pretty pic, too</td>', 'i like the border.. pretty pic, too', '2003-04-23 00:54:12.000000', NULL, 1),
(274017, 18914, 6870, '<td valign="top">Looks like you''re south of the Equator! Thanks for this amazing image. With amazing light and soft shadows, you''ve managed to capture the ripeness of this seed pod. I don''t know if you meant it this way, but it is very reminiscient of female sexuality--in a very gentle, joyful way. Wonderful. 10</td>', 'Looks like you''re south of the Equator! Thanks for this amazing image. With amazing light and soft shadows, you''ve managed to capture the ripeness of this seed pod. I don''t know if you meant it this way, but it is very reminiscient of female sexuality--in a very gentle, joyful way. Wonderful. 10', '2003-04-23 00:54:39.000000', NULL, 1),
(274018, 18701, 6523, '<td valign="top">Great colors!  Great photo!</td>', 'Great colors!  Great photo!', '2003-04-23 00:54:43.000000', NULL, 1),
(274019, 18932, 7838, '<td valign="top">its hard to belive something so pretty hurts so bad.  kind of like love, you know......</td>', 'its hard to belive something so pretty hurts so bad.  kind of like love, you know......', '2003-04-23 00:54:50.000000', NULL, 1),
(274020, 18681, 1280, '<td valign="top">Lovely subject.  Not too sure about the composition.  I''d like to see the tip of at least one.  The reflection is a nice idea!  Pretty. I love the pattern.</td>', 'Lovely subject.  Not too sure about the composition.  I''d like to see the tip of at least one.  The reflection is a nice idea!  Pretty. I love the pattern.', '2003-04-23 00:55:18.000000', NULL, 1),
(274021, 18820, 4159, '<td valign="top">Your photograph suffers from lack of a focal point and generally being small.  I think this would''ve been an intriguing macro had more of the sky/background foliage been cropped out and had you used the full available dimensions.  <br/> <br/>Probably what you''re suffering from most, though, is a popular "What IS that?"  Without a focal point, my eye wanders around this picture without finding anything to settle on.  Check the tutorial on the rule of thirds- once you get a feel for that, the pictures start to pop.</td>', 'Your photograph suffers from lack of a focal point and generally being small.  I think this would''ve been an intriguing macro had more of the sky/background foliage been cropped out and had you used the full available dimensions.   Probably what you''re suffering from most, though, is a popular "What IS that?"  Without a focal point, my eye wanders around this picture without finding anything to settle on.  Check the tutorial on the rule of thirds- once you get a feel for that, the pictures start to pop.', '2003-04-23 00:55:19.000000', NULL, 1),
(274022, 18678, 7935, '<td valign="top">bamboo pretty good shot  but looks like a flash was used  could have tried a longer exposure to try to capture more of the light filtering through the canopy.</td>', 'bamboo pretty good shot  but looks like a flash was used  could have tried a longer exposure to try to capture more of the light filtering through the canopy.', '2003-04-23 00:55:23.000000', NULL, 1),
(274023, 18952, 7838, '<td valign="top">pretty. pretty many. interesting design. a flower to look like a flower.</td>', 'pretty. pretty many. interesting design. a flower to look like a flower.', '2003-04-23 00:56:08.000000', NULL, 1),
(274024, 18358, 7838, '<td valign="top">very ery nice</td>', 'very ery nice', '2003-04-23 00:56:36.000000', NULL, 1),
(274025, 18687, 4159, '<td valign="top">This has a real tumbleweed, old west feel to it.  Nice composition, and use of color.  The sky seems to suffer from oversaturation, too much contrast, or something that''s giving it grain/artifacts.  Nice picture, though.</td>', 'This has a real tumbleweed, old west feel to it.  Nice composition, and use of color.  The sky seems to suffer from oversaturation, too much contrast, or something that''s giving it grain/artifacts.  Nice picture, though.', '2003-04-23 00:56:39.000000', NULL, 1),
(274026, 18383, 6523, '<td valign="top">Is this grape hyacinth?  Love it!  Nice arrangement -- I particularly like the way the stems are trimmed.</td>', 'Is this grape hyacinth?  Love it!  Nice arrangement -- I particularly like the way the stems are trimmed.', '2003-04-23 00:56:56.000000', NULL, 1),
(274027, 18948, 6870, '<td valign="top">Lovely night blossom. You really have captured its essence as a night-blooming flower, at least that''s what the title and image tell me. The lighting may be a bit bright and harsh, taking away from the delicacy of the bloom, but this is a wonderful image.</td>', 'Lovely night blossom. You really have captured its essence as a night-blooming flower, at least that''s what the title and image tell me. The lighting may be a bit bright and harsh, taking away from the delicacy of the bloom, but this is a wonderful image.', '2003-04-23 00:57:57.000000', NULL, 1),
(274028, 18510, 7838, '<td valign="top">title fits well for the pic. pretty colors.</td>', 'title fits well for the pic. pretty colors.', '2003-04-23 00:58:01.000000', NULL, 1),
(274031, 18921, 1280, '<td valign="top">Wonderful saturation, dof, exposure,  and composition. It all works together to make a first class image!  :-)</td>', 'Wonderful saturation, dof, exposure,  and composition. It all works together to make a first class image!  :-)', '2003-04-23 00:59:44.000000', NULL, 1),
(274032, 18783, 6870, '<td valign="top">Endlessly fascinating, the light in this photo is amazing and is an accomplishment unto itself. It emphasizes both the large outer petal and the complex inner part of the flower, The leaves in the background steal some of the focus away from the flower, I feel, where I want to only look at the flower itself.</td>', 'Endlessly fascinating, the light in this photo is amazing and is an accomplishment unto itself. It emphasizes both the large outer petal and the complex inner part of the flower, The leaves in the background steal some of the focus away from the flower, I feel, where I want to only look at the flower itself.', '2003-04-23 01:00:00.000000', NULL, 1),
(274033, 18661, 7607, '<td valign="top">Love the red against the blue of the sky. Nice point of view</td>', 'Love the red against the blue of the sky. Nice point of view', '2003-04-23 01:00:25.000000', NULL, 1),
(274034, 18630, 1280, '<td valign="top">This needs to be bigger to show it off better.  The exposure seems good.  Not always ez with white.  Pretty!</td>', 'This needs to be bigger to show it off better.  The exposure seems good.  Not always ez with white.  Pretty!', '2003-04-23 01:00:43.000000', NULL, 1),
(274035, 18971, 6325, '<td valign="top">Good detail in the primary flower. Colors seem spot on. Composition seems too open.</td>', 'Good detail in the primary flower. Colors seem spot on. Composition seems too open.', '2003-04-23 01:00:46.000000', NULL, 1),
(274036, 18744, 7838, '<td valign="top">nice. i like the freshness of the flowers amongst all the dead grasses</td>', 'nice. i like the freshness of the flowers amongst all the dead grasses', '2003-04-23 01:01:11.000000', NULL, 1),
(274038, 18960, 7607, '<td valign="top">Delicate and beautiful</td>', 'Delicate and beautiful', '2003-04-23 01:01:42.000000', NULL, 1),
(274039, 18922, 6870, '<td valign="top">The title is a bit clunky, very unlike this interesting post blossom, which is engaging and, in its own way, beautiful. The light here is magnificent, gently showing us nature''s decline. An even closer point of view would enhance the interest even further, I feel.</td>', 'The title is a bit clunky, very unlike this interesting post blossom, which is engaging and, in its own way, beautiful. The light here is magnificent, gently showing us nature''s decline. An even closer point of view would enhance the interest even further, I feel.', '2003-04-23 01:02:06.000000', NULL, 1),
(274042, 18701, 6870, '<td valign="top">I just love the composition of this photo! Amazing color capture! Despite the saturated colors here, the man''s jacket still seems a bit washed out! How can that be? Well, I don''t care. This is good photography.</td>', 'I just love the composition of this photo! Amazing color capture! Despite the saturated colors here, the man''s jacket still seems a bit washed out! How can that be? Well, I don''t care. This is good photography.', '2003-04-23 01:04:06.000000', NULL, 1),
(274043, 18820, 6523, '<td valign="top">I like the idea for this photo a lot.  I think the vine that''s creeping up would show a bit better with a tighter crop.</td>', 'I like the idea for this photo a lot.  I think the vine that''s creeping up would show a bit better with a tighter crop.', '2003-04-23 01:04:30.000000', NULL, 1),
(274044, 18534, 7607, '<td valign="top">Love the composition and natural beauty.well done</td>', 'Love the composition and natural beauty.well done', '2003-04-23 01:04:31.000000', NULL, 1),
(274048, 18885, 7838, '<td valign="top">cool shot.  like the infrared.  different effect and really makes it interesting to look at.</td>', 'cool shot.  like the infrared.  different effect and really makes it interesting to look at.', '2003-04-23 01:05:23.000000', NULL, 1),
(274049, 18853, 7607, '<td valign="top">Nice use of background. Beautiful</td>', 'Nice use of background. Beautiful', '2003-04-23 01:05:46.000000', NULL, 1),
(274050, 18358, 1280, '<td valign="top">Very nice....used to have these in upstate New York.  Dunno if they''re here in Florida.  You captured nice detail, and the shadow adds to it!!</td>', 'Very nice....used to have these in upstate New York.  Dunno if they''re here in Florida.  You captured nice detail, and the shadow adds to it!!', '2003-04-23 01:05:57.000000', NULL, 1),
(274054, 18506, 6870, '<td valign="top">What a wonderful idea. Those leaves shine like gold in this darkened forest! Looks like an oriental arrangement or composition. With a little less contrast (brights and darks), I think the image would work even better. Still, simply marvelous eye! This is great photography!</td>', 'What a wonderful idea. Those leaves shine like gold in this darkened forest! Looks like an oriental arrangement or composition. With a little less contrast (brights and darks), I think the image would work even better. Still, simply marvelous eye! This is great photography!', '2003-04-23 01:06:18.000000', NULL, 1),
(274055, 18885, 7517, '<td valign="top">I love infra-red shots.  This one is great because the subject is brighter, and isolated from anything else.  You have to let me know how you acheived the infra-red effect.  Great Shot!</td>', 'I love infra-red shots.  This one is great because the subject is brighter, and isolated from anything else.  You have to let me know how you acheived the infra-red effect.  Great Shot!', '2003-04-23 01:06:33.000000', NULL, 1),
(274057, 18951, 7838, '<td valign="top">if im not mistaken, that is Choya, right?  seen a lot of that on my last vacation to New Mexico.  nice picture</td>', 'if im not mistaken, that is Choya, right?  seen a lot of that on my last vacation to New Mexico.  nice picture', '2003-04-23 01:07:30.000000', NULL, 1),
(274058, 18701, 7517, '<td valign="top">Nice colors.  Is this a nursery of some sort?</td>', 'Nice colors.  Is this a nursery of some sort?', '2003-04-23 01:07:35.000000', NULL, 1),
(274060, 18791, 1280, '<td valign="top">Colors are wonderful and detail is good.  The problem, though, is the crashing wave in the center of the picture, distracts from the flora.</td>', 'Colors are wonderful and detail is good.  The problem, though, is the crashing wave in the center of the picture, distracts from the flora.', '2003-04-23 01:07:46.000000', NULL, 1),
(274063, 18773, 7838, '<td valign="top">kind of wish the house was a little more in focus</td>', 'kind of wish the house was a little more in focus', '2003-04-23 01:08:18.000000', NULL, 1),
(274065, 18860, 7517, '<td valign="top">Nice color.  Great subject seperation.  You stayed with the theme and definition of flora, and not some store bought prop or studio photo.  Nice shot!</td>', 'Nice color.  Great subject seperation.  You stayed with the theme and definition of flora, and not some store bought prop or studio photo.  Nice shot!', '2003-04-23 01:09:35.000000', NULL, 1),
(274071, 18916, 6325, '<td valign="top">Lovely subject. Well composed.  Good detail throughout. Could use a little peaking in the white tips. But very good.</td>', 'Lovely subject. Well composed.  Good detail throughout. Could use a little peaking in the white tips. But very good.', '2003-04-23 01:11:51.000000', NULL, 1),
(274077, 18359, 1280, '<td valign="top">Very nice!  Good diagonal, terrific detail, rich color, good contrast.</td>', 'Very nice!  Good diagonal, terrific detail, rich color, good contrast.', '2003-04-23 01:13:42.000000', NULL, 1),
(274087, 18806, 6325, '<td valign="top">Nice soft colors. The soft focus combined with the soft colors leaves nothing to center the attention. I think it would have worked better with more depth of field. Good shot, all in all.</td>', 'Nice soft colors. The soft focus combined with the soft colors leaves nothing to center the attention. I think it would have worked better with more depth of field. Good shot, all in all.', '2003-04-23 01:17:06.000000', NULL, 1),
(274090, 18367, 6325, '<td valign="top">Very good woodland scene.</td>', 'Very good woodland scene.', '2003-04-23 01:18:12.000000', NULL, 1),
(274105, 18670, 1280, '<td valign="top">Beautiful composition but this is showing up dark on my screen.</td>', 'Beautiful composition but this is showing up dark on my screen.', '2003-04-23 01:21:49.000000', NULL, 1),
(274117, 18951, 6325, '<td valign="top">Composition is good. Backgorund could have been more out of focus (smaller f#).</td>', 'Composition is good. Backgorund could have been more out of focus (smaller f#).', '2003-04-23 01:24:46.000000', NULL, 1),
(274125, 18637, 6325, '<td valign="top">Beautiful flower and vase. Well composed. The focus is much to soft for my taste for this subject.</td>', 'Beautiful flower and vase. Well composed. The focus is much to soft for my taste for this subject.', '2003-04-23 01:26:36.000000', NULL, 1),
