(276892, 18843, 5728, '<td valign="top">Amazing colors! the way the reeds are highlighted on the purple cloudy background is awesome, good eye!</td>', 'Amazing colors! the way the reeds are highlighted on the purple cloudy background is awesome, good eye!', '2003-04-24 10:16:29.000000', NULL, 1),
(276894, 18724, 5728, '<td valign="top">Excellent shallow DOF, this pic is amazing and you have composed it very well.</td>', 'Excellent shallow DOF, this pic is amazing and you have composed it very well.', '2003-04-24 10:17:10.000000', NULL, 1),
(276896, 18772, 5728, '<td valign="top">Nicely blurred out background thanx to a shallow DOF. The background is a little grainy but it isn''t such a big issue here. The lighting may be a little too harsh on the tips of some of the upper flowers, but overall a very good image.</td>', 'Nicely blurred out background thanx to a shallow DOF. The background is a little grainy but it isn''t such a big issue here. The lighting may be a little too harsh on the tips of some of the upper flowers, but overall a very good image.', '2003-04-24 10:19:16.000000', NULL, 1),
(276897, 18906, 5728, '<td valign="top">The color combinations here are awesome and mix so well together. The crop is tight but it works.</td>', 'The color combinations here are awesome and mix so well together. The crop is tight but it works.', '2003-04-24 10:20:07.000000', NULL, 1),
(276901, 18770, 5728, '<td valign="top">Lovely flowers. The lighting is a little unbalanced. The front flowers are getting maximum lighting and the back flowers are too dark. Otherwise the composition is very good and the color combination is bang on.</td>', 'Lovely flowers. The lighting is a little unbalanced. The front flowers are getting maximum lighting and the back flowers are too dark. Otherwise the composition is very good and the color combination is bang on.', '2003-04-24 10:22:27.000000', NULL, 1),
