(277212, 18917, 2891, '<td valign="top">Lose the frame.</td>', 'Lose the frame.', '2003-04-24 16:06:27.000000', NULL, 1),
(277215, 18893, 2891, '<td valign="top">Love the vivid color here.  Awesome.</td>', 'Love the vivid color here.  Awesome.', '2003-04-24 16:07:18.000000', NULL, 1),
(277217, 18838, 2891, '<td valign="top">too bad there is a stop sign in the shot.  The contrast between the dogwood (?) and the house is great.  Nice composition, but next time try walking a few more feet to the left and try to get rid of the stop sign.</td>', 'too bad there is a stop sign in the shot.  The contrast between the dogwood (?) and the house is great.  Nice composition, but next time try walking a few more feet to the left and try to get rid of the stop sign.', '2003-04-24 16:08:36.000000', NULL, 1),
(277219, 18916, 2891, '<td valign="top">Great subject.  I love seeing flowers I have never seen before.  Great clarity.  Whish you could have isolate just one of them.</td>', 'Great subject.  I love seeing flowers I have never seen before.  Great clarity.  Whish you could have isolate just one of them.', '2003-04-24 16:09:23.000000', NULL, 1),
(277222, 18383, 2891, '<td valign="top">Do not know what the issue was with this to warrent the Admin note.  Looks like an arangement on a white sheet.  A little washed out, but not bad, nonetheless.</td>', 'Do not know what the issue was with this to warrent the Admin note.  Looks like an arangement on a white sheet.  A little washed out, but not bad, nonetheless.', '2003-04-24 16:11:25.000000', NULL, 1),
(277224, 18772, 2891, '<td valign="top">Good color, nice clean background.</td>', 'Good color, nice clean background.', '2003-04-24 16:11:55.000000', NULL, 1),
(277225, 18452, 2891, '<td valign="top">Vivid color and contrast.  Nice macro.</td>', 'Vivid color and contrast.  Nice macro.', '2003-04-24 16:12:19.000000', NULL, 1),
(277234, 18536, 2891, '<td valign="top">Lovely color.</td>', 'Lovely color.', '2003-04-24 16:17:39.000000', NULL, 1),
(277236, 18976, 2891, '<td valign="top">Increased DOF here would be nice.  Great closeup, but is it too close?</td>', 'Increased DOF here would be nice.  Great closeup, but is it too close?', '2003-04-24 16:18:35.000000', NULL, 1),
(277242, 18639, 2891, '<td valign="top">Pretty image.  However it feels more like a snapshot, especially with the top half ot the photo out of focus and pixelated.</td>', 'Pretty image.  However it feels more like a snapshot, especially with the top half ot the photo out of focus and pixelated.', '2003-04-24 16:20:20.000000', NULL, 1),
(277243, 18733, 2891, '<td valign="top">Nice flower, bad background.</td>', 'Nice flower, bad background.', '2003-04-24 16:20:39.000000', NULL, 1),
