INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(277268, 18912, 4536, '<td valign="top">Very nice colors and composition. I think these are also called Lupine. The washed out sky is distracting, either a higher angle or cropping down would ,IMO, improve this shot.</td>', 'Very nice colors and composition. I think these are also called Lupine. The washed out sky is distracting, either a higher angle or cropping down would ,IMO, improve this shot.', '2003-04-24 16:43:36.000000', NULL, 1),
(277281, 18860, 2586, '<td valign="top">Gorgeous, gorgeous, gorgeous! I love the two front flowers, purple and its complimentary yellow. That purple tulip is so alive. Dof is superb. And so are the colors, they are warm, rich, and lively and none of them clash.  10 Journey</td>', 'Gorgeous, gorgeous, gorgeous! I love the two front flowers, purple and its complimentary yellow. That purple tulip is so alive. Dof is superb. And so are the colors, they are warm, rich, and lively and none of them clash.  10 Journey', '2003-04-24 16:54:46.000000', NULL, 1),
(277284, 18383, 4536, '<td valign="top">Very clever and well done.</td>', 'Very clever and well done.', '2003-04-24 16:57:04.000000', NULL, 1),
(277285, 18741, 2586, '<td valign="top">Just wished that front fennel branch wasn''t there; it''s too much in sharp focus. Appreciate the beauty of the flower opening up. 6 Journey</td>', 'Just wished that front fennel branch wasn''t there; it''s too much in sharp focus. Appreciate the beauty of the flower opening up. 6 Journey', '2003-04-24 16:57:07.000000', NULL, 1),
(277288, 18935, 1031, '<td valign="top">More separation from the background would help make the flowers stand out even more. It''s hard to restrict the DOF on many digital cameras (like mine). In this case, you might have been able to stand on a chair or something to get more distance between the hand and the background.</td>', 'More separation from the background would help make the flowers stand out even more. It''s hard to restrict the DOF on many digital cameras (like mine). In this case, you might have been able to stand on a chair or something to get more distance between the hand and the background.', '2003-04-24 16:59:11.000000', NULL, 1),
(277289, 18956, 2586, '<td valign="top">I always appreciate hosta leaves, but in real and in pictures. You gave them a nice, almost abstract here and there, treatment. Yet, there isn''t any particular area in this shot that you emphasized and my eye is wandering around the picture plane and not quite knowing where it should rest. 6 Journey</td>', 'I always appreciate hosta leaves, but in real and in pictures. You gave them a nice, almost abstract here and there, treatment. Yet, there isn''t any particular area in this shot that you emphasized and my eye is wandering around the picture plane and not quite knowing where it should rest. 6 Journey', '2003-04-24 16:59:29.000000', NULL, 1),
(277291, 18834, 2586, '<td valign="top">Nice image. Would have cropped the background beyond the tulip field off; it''s a bit distracting. 7 Journey</td>', 'Nice image. Would have cropped the background beyond the tulip field off; it''s a bit distracting. 7 Journey', '2003-04-24 17:00:46.000000', NULL, 1),
(277295, 18627, 1031, '<td valign="top">Not only a pretty flower I don''t think I''ve seen live, but it played a significant role in medical history...now, where''s the four-leafed stem? With a little (hyperactive) imagination your view resembles a shot of those Easter Island statues...</td>', 'Not only a pretty flower I don''t think I''ve seen live, but it played a significant role in medical history...now, where''s the four-leafed stem? With a little (hyperactive) imagination your view resembles a shot of those Easter Island statues...', '2003-04-24 17:03:12.000000', NULL, 1),
(277296, 18367, 2586, '<td valign="top">This is really sweet. It DOES give me the sensation of walking around and my eye catching something of beauty that is humbly hidden unless you look carefully. I really like the saturated colors. Yellow and green is a color combination that clashes in painting but in nature it never does; beats me! This picture is really pleasant to contemplate. 8 Journey</td>', 'This is really sweet. It DOES give me the sensation of walking around and my eye catching something of beauty that is humbly hidden unless you look carefully. I really like the saturated colors. Yellow and green is a color combination that clashes in painting but in nature it never does; beats me! This picture is really pleasant to contemplate. 8 Journey', '2003-04-24 17:04:03.000000', NULL, 1),
(277298, 18634, 1031, '<td valign="top">Lighting''s a little harsh for my taste, but like the focus, DOF, color...</td>', 'Lighting''s a little harsh for my taste, but like the focus, DOF, color...', '2003-04-24 17:05:24.000000', NULL, 1),
(277299, 18480, 2586, '<td valign="top">Too much of a good thing, i guess - at least for my taste.  Would have preferred if one or two of these beautiful flowers had been emphasized. 5 Journey</td>', 'Too much of a good thing, i guess - at least for my taste.  Would have preferred if one or two of these beautiful flowers had been emphasized. 5 Journey', '2003-04-24 17:06:08.000000', NULL, 1),
