(277986, 18536, 5728, '<td valign="top">Good idea and well captured. The composition is very good. The top petal seems a little blurry though.</td>', 'Good idea and well captured. The composition is very good. The top petal seems a little blurry though.', '2003-04-25 10:56:16.000000', NULL, 1),
(277995, 18944, 5728, '<td valign="top">Choice capture, that green with the light shining through looks amazing! The angle you chose is very effective.<br/></td>', 'Choice capture, that green with the light shining through looks amazing! The angle you chose is very effective.', '2003-04-25 10:57:16.000000', NULL, 1),
(278060, 18731, 5728, '<td valign="top">Those fields of tulips take a lot of the gloom out of that gloomy day :-) I particularly like the perspective of your pic, clever idea.</td>', 'Those fields of tulips take a lot of the gloom out of that gloomy day :-) I particularly like the perspective of your pic, clever idea.', '2003-04-25 11:05:32.000000', NULL, 1),
