INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(278135, 18487, 5728, '<td valign="top">Amazing effect you''ve captured with those raindrops. You''ve brought out so much detail here.</td>', 'Amazing effect you''ve captured with those raindrops. You''ve brought out so much detail here.', '2003-04-25 11:24:18.000000', NULL, 1),
(278136, 18367, 5728, '<td valign="top">Yellow on green is always a great color combination. That and your nice deep DOF makes this image very good!</td>', 'Yellow on green is always a great color combination. That and your nice deep DOF makes this image very good!', '2003-04-25 11:25:19.000000', NULL, 1),
(278137, 18504, 5728, '<td valign="top">Very good decision to use that crisp blue sky as a background, it really enhances this pic.</td>', 'Very good decision to use that crisp blue sky as a background, it really enhances this pic.', '2003-04-25 11:25:58.000000', NULL, 1),
(278138, 18956, 3247, '<td valign="top">This is my favorite.  It''s the swirl patern. - 9</td>', 'This is my favorite.  It''s the swirl patern. - 9', '2003-04-25 11:26:03.000000', NULL, 1),
(278140, 18484, 5728, '<td valign="top">Very crisp and detailed. Your flowers are enhanced so much more with the shallow DOF, good job!</td>', 'Very crisp and detailed. Your flowers are enhanced so much more with the shallow DOF, good job!', '2003-04-25 11:26:36.000000', NULL, 1),
(278145, 18359, 3247, '<td valign="top">Beautiful composition. The fade is a wonderful adition.</td>', 'Beautiful composition. The fade is a wonderful adition.', '2003-04-25 11:27:38.000000', NULL, 1),
(278146, 18549, 5728, '<td valign="top">Beautiful! Very symmetric and colorful. It could be just a tad sharper, the lower petals appear a little blurry.</td>', 'Beautiful! Very symmetric and colorful. It could be just a tad sharper, the lower petals appear a little blurry.', '2003-04-25 11:27:40.000000', NULL, 1),
(278150, 18386, 3247, '<td valign="top">DOF is just wonderful.  Great choice of subject.  The black background is perfect choice.</td>', 'DOF is just wonderful.  Great choice of subject.  The black background is perfect choice.', '2003-04-25 11:28:53.000000', NULL, 1),
(278151, 18480, 5728, '<td valign="top">Beautiful pic! Those colors have come out very crisp. I would have shallowed up the DOF a little so as to blur the background a tad. The wooden floor is also full in focus.</td>', 'Beautiful pic! Those colors have come out very crisp. I would have shallowed up the DOF a little so as to blur the background a tad. The wooden floor is also full in focus.', '2003-04-25 11:29:06.000000', NULL, 1),
(278154, 18714, 5728, '<td valign="top">An awesome orange flower you''ve captured. The perspective is very interesting and works!</td>', 'An awesome orange flower you''ve captured. The perspective is very interesting and works!', '2003-04-25 11:30:00.000000', NULL, 1),
(278157, 18770, 3247, '<td valign="top">Good compostion.  Great DOF.  Lighting is too harsh.</td>', 'Good compostion.  Great DOF.  Lighting is too harsh.', '2003-04-25 11:30:37.000000', NULL, 1),
(278160, 18974, 5728, '<td valign="top">Choice macro. The lighting is a little uneven, the lower part of the flower appears a tad too dark. There probably wasn''t too much you could have done about that though. Otherwise a very good pic.</td>', 'Choice macro. The lighting is a little uneven, the lower part of the flower appears a tad too dark. There probably wasn''t too much you could have done about that though. Otherwise a very good pic.', '2003-04-25 11:31:45.000000', NULL, 1),
(278161, 18836, 3247, '<td valign="top">Too bad you couldn''t have photographed a more colorful insect. ery good photo.</td>', 'Too bad you couldn''t have photographed a more colorful insect. ery good photo.', '2003-04-25 11:31:56.000000', NULL, 1),
(278162, 18627, 5728, '<td valign="top">Lovely flora. The reds and greens match well together. The decision not to include a border was good.</td>', 'Lovely flora. The reds and greens match well together. The decision not to include a border was good.', '2003-04-25 11:32:32.000000', NULL, 1),
(278164, 18634, 5728, '<td valign="top">Beautiful!! The natural lighting is perfect. You can be proud of this pic.</td>', 'Beautiful!! The natural lighting is perfect. You can be proud of this pic.', '2003-04-25 11:33:20.000000', NULL, 1),
(278165, 18904, 3247, '<td valign="top">Too dark.  a little more light and color is needed. Wonderful idea.</td>', 'Too dark.  a little more light and color is needed. Wonderful idea.', '2003-04-25 11:33:20.000000', NULL, 1),
(278166, 18951, 5728, '<td valign="top">I''ve never seen this kind of cactus before. Nice composition, maybe a little teak on the saturation could have richened those greens more, otherwise a top pic.</td>', 'I''ve never seen this kind of cactus before. Nice composition, maybe a little teak on the saturation could have richened those greens more, otherwise a top pic.', '2003-04-25 11:35:24.000000', NULL, 1),
(278167, 18758, 3247, '<td valign="top">More focus needed.  Too much green cast.  This is a difficult shot due to the softness of the subject.  The camera has a hard time adjusting and hence poor focus.  I have tried this many times without great sucess.</td>', 'More focus needed.  Too much green cast.  This is a difficult shot due to the softness of the subject.  The camera has a hard time adjusting and hence poor focus.  I have tried this many times without great sucess.', '2003-04-25 11:35:27.000000', NULL, 1),
(278168, 18821, 3247, '<td valign="top">Wonderful.  Loe this shot, especially with the highlights on the cattails.  This photo calls for the foreground to be in focus and the background out.</td>', 'Wonderful.  Loe this shot, especially with the highlights on the cattails.  This photo calls for the foreground to be in focus and the background out.', '2003-04-25 11:37:00.000000', NULL, 1),
