(278213, 18705, 7752, '<td valign="top">Wonderful composition.  Congratulations.</td>', 'Wonderful composition.  Congratulations.', '2003-04-25 12:57:44.000000', NULL, 1),
(278216, 18852, 7752, '<td valign="top">Very interesting composition and perfect technique.  Great!</td>', 'Very interesting composition and perfect technique.  Great!', '2003-04-25 12:59:36.000000', NULL, 1),
