(278536, 18968, 4793, '<td valign="top">Beautiful colors and comp. just a bit out of focus.</td>', 'Beautiful colors and comp. just a bit out of focus.', '2003-04-25 16:01:37.000000', NULL, 1),
(278537, 18809, 4793, '<td valign="top">Beautiful</td>', 'Beautiful', '2003-04-25 16:03:46.000000', NULL, 1),
