(280117, 18935, 4871, '<td valign="top">Fantastic! If the hand wasn''t there you''d think that these plants were growing in the ground - are they??? Well done!</td>', 'Fantastic! If the hand wasn''t there you''d think that these plants were growing in the ground - are they??? Well done!', '2003-04-27 22:10:51.000000', NULL, 1),
